  const domain = hostOf(e.source_url) || e.normalized_domain || '';
  if (!domain || !/\.[a-z]{2,}$/i.test(domain)) {
    return { json: { ...out, validation_status: 'REJECTED', rejection_reason: 'ERR_MALFORMED_URL', rejection_veto: true } };
