    decision_maker_supported: dm_supported,
    evidence_count: (e.extracted_evidence_snippets || []).length,
    verification_flags: flags,
    confidence_level: confidence,
    validation_errors: errors,
    validated_at: new Date().toISOString()
  } };
});

const cfg = $('Parameter Normalizer').first().json;
const lc = s => String(s || '').toLowerCase();
const SENIOR = /(founder|co-founder|ceo|cto|chief|managing director|president|owner|vp|vice president|director)/i;

return $input.all().map(item => {
  const e = item.json;

  if (e.validation_status !== 'VALIDATED') {
    return { json: { ...e, lead_score: 0, sub_scores: {}, routing_target: 'QUARANTINE', score_reason: e.rejection_reason || 'NOT_VALIDATED' } };
  }

  const dm = e.key_decision_maker || {};

  // Industry (30%): 100 direct match, 50 adjacent tech, 0 mismatch
  const ind = lc(e.industry_sector + ' ' + e.company_description);
  const target = lc(cfg.target_industry);
  const words = target.split(/\s+/).filter(w => w.length > 3);
  const direct = ind.includes(target) || (words.length && words.every(w => ind.includes(w))) || /\bit services\b|software|technology|digital|web development/.test(ind);
  const s_ind = direct ? 100 : (/(tech|data|cloud|ai|automation)/.test(ind) ? 50 : 0);

  // ICP size (20%): 100 matches target, 50 unknown, 0 enterprise or solo
  const size = e.estimated_employee_range;
  let s_icp;
  if (cfg.company_size_range !== 'ALL' && size === cfg.company_size_range) s_icp = 100;
  else if (size === 'UNKNOWN') s_icp = 50;
  else if (size === '501+' || size === '1-10') s_icp = 0;
  else s_icp = 50;

  // Geography (15%): 100 HQ in target, 50 regional office, 0 foreign
  const geo = lc(cfg.target_geography);
  const hq = lc(e.headquarters_location);
  const indiaWords = /india|gujarat|maharashtra|pune|mumbai|bengaluru|bangalore|delhi|hyderabad|chennai|ahmedabad|punjab/;
  let s_geo;
  if (!hq) {
    // HQ not labelled: is the target place on the page at all (address, footer, contact)?
    const place = geo.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    s_geo = place && new RegExp('\\b' + place + '\\b').test(lc(e.page_text)) ? 75 : 25;
  }
  else if (hq.includes(geo) || (geo === 'india' && indiaWords.test(hq))) s_geo = 100;
  else if (indiaWords.test(hq)) s_geo = 50;
  else s_geo = 0;

  // Decision maker (15%): 100 supported senior, 50 supported other, 0 none or unsupported
  let s_role = 0;
  if (e.decision_maker_supported) s_role = SENIOR.test(dm.designation || '') ? 100 : 50;

  // Evidence (20%): 100 for 2 or more verified quotes, 50 for one, 0 for none
  const n = e.evidence_count || 0;
  const s_evid = n >= 2 ? 100 : (n === 1 ? 50 : 0);

  const lead_score = Math.round(0.30 * s_ind + 0.20 * s_icp + 0.15 * s_geo + 0.15 * s_role + 0.20 * s_evid);
  const routing_target = lead_score >= cfg.min_lead_score ? 'MASTER' : (lead_score >= 60 ? 'REVIEW' : 'QUARANTINE');

  return { json: { ...e, lead_score, sub_scores: { industry: s_ind, icp: s_icp, geography: s_geo, role: s_role, evidence: s_evid }, routing_target } };
});

const staticData = $getWorkflowStaticData('global');
staticData.seen = staticData.seen || {};

// Hash: try SHA-256, fall back to a deterministic pure-JS hash
function hashOf(s) {
  try {
    const c = require('crypto');
    return 'sha256:' + c.createHash('sha256').update(s).digest('hex').slice(0, 32);
  } catch (e) {
    let h1 = 0xdeadbeef, h2 = 0x41c6ce57;
    for (let i = 0; i < s.length; i++) {
      const ch = s.charCodeAt(i);
      h1 = Math.imul(h1 ^ ch, 2654435761);
      h2 = Math.imul(h2 ^ ch, 1597334677);
    }
    h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
    h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
    return 'h64:' + (4294967296 * (2097151 & h2) + (h1 >>> 0)).toString(16);
  }
}

// Normalize: lowercase, strip www, strip common subdomains and country-level duplicates
function canonicalDomain(d) {
  let x = String(d || '').toLowerCase().trim().replace(/^www\./, '');
  x = x.replace(/^(m|mobile|portal|app|web|en|in)\./, '');
  return x;
}

const batchSeen = new Set();
return $input.all().map(item => {
  const e = item.json;
  const domain = canonicalDomain(e.normalized_domain);
  if (!domain) return { json: { ...e, dedup_status: 'NO_DOMAIN' } };
  const key = hashOf(domain);
  const emailKey = e.verified_email ? hashOf(String(e.verified_email).toLowerCase()) : null;

  const dupInRun = batchSeen.has(key);
  const dupAcross = !!staticData.seen[key];
  batchSeen.add(key);

  if (dupInRun || dupAcross) {
    return { json: { ...e, domain_hash: key, dedup_status: dupInRun ? 'DUPLICATE_IN_RUN' : 'DUPLICATE_PREVIOUS_RUN', routing_target: 'DUPLICATE', first_seen_at: staticData.seen[key] || null } };
  }
  // Register only leads that will be stored (not quarantine vetoes with no value)
  if (e.extraction_status === 'EXTRACTED') staticData.seen[key] = new Date().toISOString();
  return { json: { ...e, domain_hash: key, email_hash: emailKey, normalized_domain: domain, dedup_status: 'NEW' } };
});

const ist = d => new Date(d.getTime() + 330 * 60000).toISOString().slice(0, 19).replace('T', ' ') + ' IST';
const nowDate = new Date();
const now = ist(nowDate);          // shown in the sheets (IST)
const now_utc = nowDate.toISOString(); // for machines
return $input.all().map(i => {
  const e = i.json;
  const dm = e.key_decision_maker || {};
  const id = String(e.domain_hash || e.result_id || '').replace(/[^a-z0-9]/gi, '').slice(-10).toUpperCase();
  const score = e.lead_score ?? 0;
  const route = e.routing_target || '';
  const routeReason =
    route === 'MASTER' ? 'score ' + score + ' meets the master threshold' :
    route === 'REVIEW' ? 'score ' + score + ' in review band (60-79): needs human check' :
    'score ' + score + ' below 60';
  return { json: {
    ...e,
    review_id: 'REV-' + id, rejection_id: 'REJ-' + id,
    master_lead_id: 'MLD-' + id,
    contact_name: dm.full_name || '', designation: dm.designation || '',
    sub_scores_text: JSON.stringify(e.sub_scores || {}),
    evidence_text: (e.extracted_evidence_snippets || []).join(' | '),
    flags_text: (e.verification_flags || []).join(','),
    reason_text: e.score_reason || e.rejection_reason || routeReason,
    now, now_utc
  } };
});

return $input.all().map(i => {
  const j = i.json;
  const m = String(j.source_url || '').match(/^(https?:\/\/[^\/?#]+)(\/[^?#]*)?/i);
  const origin = m ? m[1] : '';
  const path = m && m[2] ? m[2].toLowerCase() : '';
  const isAboutLike = /about|team|founder|leadership|contact/.test(path);
  // Respect blocks: never re-hit a site that already failed or was blocked.
  // Already an about/contact page: no second fetch needed.
  const eligible = origin && j.scrape_status === 'SCRAPED' && !isAboutLike;
  const about_url = eligible ? origin + '/about' : '';
  return { json: { ...j, about_url } };
});

const base = $('Add About URL').all();
const NAMED = { nbsp:' ', amp:'&', lt:'<', gt:'>', quot:'"', apos:"'" };
const decode = s => s.replace(/&#x([0-9a-f]+);/gi,(m,h)=>String.fromCharCode(parseInt(h,16))).replace(/&#(\d+);/g,(m,d)=>String.fromCharCode(+d)).replace(/&([a-z]+);/gi,(m,n)=>NAMED[n.toLowerCase()]??m);
const ROLE = /\b(founder|co-founder|ceo|cto|coo|director|managing|owner|partner|president|head of)\b/i;

return $input.all().map((item, i) => {
  const j = base[i] ? base[i].json : {};
  if (!j.about_url) return { json: { ...j, about_status: 'ABOUT_SKIPPED' } };
  const status = item.json.statusCode || item.json.status || null;
  const body = typeof item.json.body === 'string' ? item.json.body : (typeof item.json.data === 'string' ? item.json.data : '');
  if (!body || (status && status >= 400)) return { json: { ...j, about_status: 'ABOUT_SKIPPED' } };

  let t = body.replace(/<(script|style|noscript|svg|iframe|nav|header|footer)[\s\S]*?<\/\1>/gi,' ').replace(/<!--[\s\S]*?-->/g,' ').replace(/<(br|\/p|\/div|\/li|\/h[1-6])\s*\/?>/gi,'\n').replace(/<[^>]+>/g,' ');
  t = decode(t).replace(/[ \t\r\f\v]+/g,' ').replace(/\s*\n\s*/g,'\n').replace(/\n{2,}/g,'\n').trim();

  // keep only lines not already on the main page, and only substantive ones
  const seen = new Set(String(j.page_text || '').split('\n').map(s => s.trim()));
  const fresh = t.split('\n').map(s => s.trim())
    .filter(l => l && !seen.has(l) && (l.length >= 40 || l.includes('@') || ROLE.test(l)))
    .join('\n');

  if (fresh.length < 100) return { json: { ...j, about_status: 'ABOUT_DUPLICATE_OR_EMPTY' } };
  return { json: { ...j, page_text: String(j.page_text || '') + '\n--- ABOUT PAGE ---\n' + fresh.slice(0, 3000), about_status: 'ABOUT_ADDED' } };
});

// Only brand-new leads reach the Master append. Existing rows are never touched,
// so human_approval, outreach_status and created_at can never be reset by a re-run.
const canon = d => String(d || '').toLowerCase().trim().replace(/^www\./, '');
const existing = new Set();
for (const it of $input.all()) {
  const d = canon(it.json.normalized_domain);
  if (d) existing.add(d);
}
const seen = new Set();
const out = [];
for (const it of $('Prepare Rows').all()) {
  const e = it.json;
  if (e.routing_target !== 'MASTER') continue;
  const d = canon(e.normalized_domain);
  if (!d || existing.has(d) || seen.has(d)) continue;
  seen.add(d);
  out.push({ json: e });
}
return out;
